import { Component, computed, input } from '@angular/core';
import type { EChartsOption } from 'echarts';
import { HrmChart } from './hrm-chart';
import { chartTokenReader } from './chart-token';

/** hrm-kpi-gauge — đồng hồ đo % đạt mục tiêu: KPI hoàn thành bao nhiêu, còn cách đích bao xa.
 *  Cung tô theo tiến độ, số lớn ở giữa. Domain HRM: KPI cá nhân/phòng ban, tiến độ tuyển dụng,
 *  tỉ lệ chuyên cần, mức hoàn thành mục tiêu quý. */
@Component({
  selector: 'hrm-kpi-gauge',
  imports: [HrmChart],
  template: `<hrm-chart [option]="option()" [height]="height()" />`,
  host: { class: 'hrm-kpi-gauge' },
})
export class HrmKpiGauge {
  /** Giá trị hiện tại (0..max). */
  readonly value = input(0);
  readonly max = input(100);
  /** Nhãn dưới số (VD "Hoàn thành") — bên gọi cấp. */
  readonly label = input('');
  /** Hậu tố số giữa (VD "%"). */
  readonly suffix = input('%');
  readonly height = input(260);

  protected readonly option = computed<EChartsOption>(() => {
    const v = this.value();
    const pct = Math.round((v / this.max()) * 100);
    // Màu cung theo mức: đỏ < 50, vàng < 80, xanh >= 80 (đọc token lúc dựng option).
    const tk = chartTokenReader();
    const track = tk('--bg-surface-subtle', '--border-soft');
    const color = pct < 50 ? tk('--error-base', '--data-1') : pct < 80 ? tk('--warning-base', '--data-4') : tk('--success-base', '--data-2');
    return {
      series: [{
        type: 'gauge', min: 0, max: this.max(), startAngle: 210, endAngle: -30,
        radius: '96%', center: ['50%', '58%'],
        progress: { show: true, width: 14, roundCap: true, itemStyle: { color } },
        axisLine: { lineStyle: { width: 14, color: [[1, track]] } },
        pointer: { show: false },
        axisTick: { show: false }, splitLine: { show: false }, axisLabel: { show: false },
        anchor: { show: false },
        title: { show: !!this.label(), offsetCenter: [0, '38%'], fontSize: 14, color: tk('--text-sub', '--text-body') },
        detail: { valueAnimation: true, offsetCenter: [0, '2%'], fontSize: 34, fontWeight: 'bolder',
          color: tk('--text-strong', '--text-body'), formatter: (x: number) => `${Math.round(x)}${this.suffix()}` },
        data: [{ value: v, name: this.label() }],
      }],
    };
  });
}
